        /// <threadsafety>It is safe to call this macro from any thread.</threadsafety>
        /// <since>This macro is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_PIXELTYPE">SDL_PIXELTYPE</seealso></SDLWiki>
        public static uint Pixeltype(uint format) => (((format) >> 24) & 0x0F);

    }
}
